421	+export interface CrowdSlot { x: number; z: number; yaw: number; type: BoatTypeId; len: number; variant: number; led: number; name: number; phase: number }
422	+
423	+const B = CONFIG.boats;
424	+
425	+/* Vùng cấm cho tâm tàu có nửa chiều dài halfLen (tàu có thể xoay ngang nên lấy halfLen cho cả hai trục) */
426	+export function btInExclusion(x: number, z: number, halfLen: number): boolean {
427	+  const E = B.exclusion;
428	+  if (Math.abs(z - E.tunnelZ) < E.tunnelHalf + halfLen) return true;                                   // hành lang Hầm
429	+  if (E.bridgeZ.some((bz) => Math.abs(z - bz) < E.bridgeHalf + halfLen)) return true;                   // dưới mặt cầu
430	+  if (Math.abs(z - E.swingZ) < E.swingHalfZ && Math.abs(x) < E.swingHalfX + halfLen) return true;      // vòng quay + luồng Cầu sông Hàn
431	+  if (E.lanes.some((lx) => Math.abs(x - lx) < E.laneHalf + halfLen)) return true;                      // làn tàu chạy
432	+  return Math.abs(x) > E.bankX - E.bankMargin - halfLen;                                               // sát kè
433	+}
434	+
435	+/* Rải tàu bằng thử–loại trong từng cụm; kiểu / biến thể / màu LED lấy từ danh sách tổ hợp đã xáo để không trùng trong một cụm */
436	+export function btCrowdSlots(cfg = B.crowd): CrowdSlot[] {
437	+  const rnd = rng(cfg.seed), out: CrowdSlot[] = [];
438	+  const E = B.exclusion, xMax = E.bankX - E.bankMargin;
439	+  for (const g of cfg.groups) {
440	+    const combos: [BoatTypeId, number, number][] = [];
441	+    for (const t of ['A', 'B', 'C'] as BoatTypeId[]) for (let v = 0; v < B.variants; v++) for (let l = 0; l < B.led.colors.length; l++) combos.push([t, v, l]);
442	+    for (let i = combos.length - 1; i > 0; i--) { const j = Math.floor(rnd() * (i + 1)); [combos[i], combos[j]] = [combos[j], combos[i]]; }
443	+    const first = out.length;
444	+    for (let k = 0, tries = 0; k < g.n; tries++) {
445	+      if (tries > 5000) throw new Error(`btCrowdSlots: không đủ chỗ cho cụm ${g.name}`);
446	+      const [type, variant, led] = combos[k], [lo, hi] = B.types[type].len, len = lo + rnd() * (hi - lo);
447	+      const x = (rnd() * 2 - 1) * xMax, z = g.zMin + rnd() * (g.zMax - g.zMin);
448	+      if (btInExclusion(x, z, len / 2)) continue;
449	+      if (out.slice(first).some((o) => Math.hypot(o.x - x, o.z - z) < cfg.minGap)) continue;
450	+      const yaw = (rnd() < 0.5 ? 0 : Math.PI) + (rnd() * 2 - 1) * cfg.yawSpread;
451	+      out.push({ x, z, yaw, type, len, variant, led, name: Math.floor(rnd() * B.names.length), phase: rnd() * Math.PI * 2 });
452	+      k++;
453	+    }
454	+  }
455	+  return out;
456	+}
457	+
458	+/* Mức hiện của tàu thứ i (0..1): mỗi tàu hiện dần trong một khúc riêng của khoảng nightOn (so le như vanished()),
459	+   rồi về bến theo boatAway (bão) cũng so le. Không giảm khi night tăng. */
460	+export function btCrowdAlpha(i: number, n: number, night: number, boatAway: number): number {
461	+  const C = B.crowd, [n0, n1] = C.nightOn, w = C.rampFrac;
462	+  const h = (i * 0.6180339887) % 1, start = h * (1 - w);
463	+  const t = clamp((night - n0) / (n1 - n0), 0, 1);
464	+  const on = smooth(clamp((t - start) / w, 0, 1));
465	+  const away = smooth(clamp((boatAway - start) / w, 0, 1));
466	+  return on * (1 - away);
467	+}
